//===--------------------------------------------------------------------===//
// Commit requests
//===--------------------------------------------------------------------===//
optional_idx RESTCommitRequest::TypeFromPath(const string &path) {
	if (path == "create_schema") {
		return static_cast<idx_t>(RESTCommitRequestType::CREATE_SCHEMA);
	}
	if (path == "create_table") {
		return static_cast<idx_t>(RESTCommitRequestType::CREATE_TABLE);
	}
	if (path == "create_view") {
		return static_cast<idx_t>(RESTCommitRequestType::CREATE_VIEW);
	}
	if (path == "create_macro") {
		return static_cast<idx_t>(RESTCommitRequestType::CREATE_MACRO);
	}
	if (path == "alter") {
		return static_cast<idx_t>(RESTCommitRequestType::ALTER);
	}
	if (path == "drop") {
		return static_cast<idx_t>(RESTCommitRequestType::DROP);
	}
	if (path == "set_option") {
		return static_cast<idx_t>(RESTCommitRequestType::SET_OPTION);
	}
	if (path == "insert_rows") {
		return static_cast<idx_t>(RESTCommitRequestType::INSERT_ROWS);
	}
	if (path == "insert_files") {
		return static_cast<idx_t>(RESTCommitRequestType::INSERT_FILES);
	}
	if (path == "delete_data") {
		return static_cast<idx_t>(RESTCommitRequestType::DELETE_DATA);
	}
	return optional_idx();
}

//! Reads the parameters of a commit request
static unique_ptr<RESTCommitRequest> ReadCommitRequest(RESTCommitRequestType type, RESTJsonIn parameters) {
	switch (type) {
	case RESTCommitRequestType::CREATE_SCHEMA:
		return make_uniq<RESTCreateSchemaRequest>(DuckLakeRESTSerializer::Read<RESTCreateSchemaRequest>(parameters));
	case RESTCommitRequestType::CREATE_TABLE:
		return make_uniq<RESTCreateTableRequest>(DuckLakeRESTSerializer::Read<RESTCreateTableRequest>(parameters));
	case RESTCommitRequestType::CREATE_VIEW:
		return make_uniq<RESTCreateViewRequest>(DuckLakeRESTSerializer::Read<RESTCreateViewRequest>(parameters));
	case RESTCommitRequestType::CREATE_MACRO:
		return make_uniq<RESTCreateMacroRequest>(DuckLakeRESTSerializer::Read<RESTCreateMacroRequest>(parameters));
	case RESTCommitRequestType::ALTER:
		return make_uniq<RESTAlterRequest>(DuckLakeRESTSerializer::Read<RESTAlterRequest>(parameters));
	case RESTCommitRequestType::DROP:
		return make_uniq<RESTDropRequest>(DuckLakeRESTSerializer::Read<RESTDropRequest>(parameters));
	case RESTCommitRequestType::SET_OPTION:
		return make_uniq<RESTSetOptionRequest>(DuckLakeRESTSerializer::Read<RESTSetOptionRequest>(parameters));
	case RESTCommitRequestType::INSERT_ROWS:
		return make_uniq<RESTInsertRowsRequest>(DuckLakeRESTSerializer::Read<RESTInsertRowsRequest>(parameters));
	case RESTCommitRequestType::INSERT_FILES:
		return make_uniq<RESTInsertFilesRequest>(DuckLakeRESTSerializer::Read<RESTInsertFilesRequest>(parameters));
	case RESTCommitRequestType::DELETE_DATA:
		return make_uniq<RESTDeleteDataRequest>(DuckLakeRESTSerializer::Read<RESTDeleteDataRequest>(parameters));
	default:
		throw InternalException("Unsupported RESTCommitRequestType");
	}
}

// commit requests are a union: an object with the parameters of the request under the name of its endpoint
JSONMutableValue RESTCommitRequestCodec::Write(JSONWriter &writer, const RESTCommitRequest &value) {
	auto result = writer.CreateObject();
	switch (value.type) {
	case RESTCommitRequestType::CREATE_SCHEMA:
		result.Add("create_schema", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTCreateSchemaRequest>()));
		break;
	case RESTCommitRequestType::CREATE_TABLE:
		result.Add("create_table", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTCreateTableRequest>()));
		break;
	case RESTCommitRequestType::CREATE_VIEW:
		result.Add("create_view", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTCreateViewRequest>()));
		break;
	case RESTCommitRequestType::CREATE_MACRO:
		result.Add("create_macro", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTCreateMacroRequest>()));
		break;
	case RESTCommitRequestType::ALTER:
		result.Add("alter", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTAlterRequest>()));
		break;
	case RESTCommitRequestType::DROP:
		result.Add("drop", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTDropRequest>()));
		break;
	case RESTCommitRequestType::SET_OPTION:
		result.Add("set_option", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTSetOptionRequest>()));
		break;
	case RESTCommitRequestType::INSERT_ROWS:
		result.Add("insert_rows", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTInsertRowsRequest>()));
		break;
	case RESTCommitRequestType::INSERT_FILES:
		result.Add("insert_files", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTInsertFilesRequest>()));
		break;
	case RESTCommitRequestType::DELETE_DATA:
		result.Add("delete_data", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTDeleteDataRequest>()));
		break;
	default:
		throw InternalException("Unsupported RESTCommitRequestType");
	}
	return result;
}

void RESTCommitRequestCodec::Read(RESTJsonIn in, unique_ptr<RESTCommitRequest> &result) {
	auto members = in.Members();
	if (members.size() != 1) {
		throw InvalidInputException("DuckLake REST: a request of commit_transaction has to be an object with exactly "
		                            "one member, the parameters of the request under the name of its endpoint");
	}
	auto &path = members[0].first;
	auto type = RESTCommitRequest::TypeFromPath(path);
	if (!type.IsValid()) {
		throw InvalidInputException("Unsupported request \"%s\" in commit_transaction", path);
	}
	result = ReadCommitRequest(static_cast<RESTCommitRequestType>(type.GetIndex()), members[0].second);
}

void DuckLakeRESTCommitHandler::Apply(RESTCommitRequest &request) {
	switch (request.type) {
	case RESTCommitRequestType::CREATE_SCHEMA:
		CreateSchema(request.Cast<RESTCreateSchemaRequest>());
		break;
	case RESTCommitRequestType::CREATE_TABLE:
		CreateTable(request.Cast<RESTCreateTableRequest>());
		break;
	case RESTCommitRequestType::CREATE_VIEW:
		CreateView(request.Cast<RESTCreateViewRequest>());
		break;
	case RESTCommitRequestType::CREATE_MACRO:
		CreateMacro(request.Cast<RESTCreateMacroRequest>());
		break;
	case RESTCommitRequestType::ALTER:
		Alter(request.Cast<RESTAlterRequest>());
		break;
	case RESTCommitRequestType::DROP:
		Drop(request.Cast<RESTDropRequest>());
		break;
	case RESTCommitRequestType::SET_OPTION:
		SetOption(request.Cast<RESTSetOptionRequest>());
		break;
	case RESTCommitRequestType::INSERT_ROWS:
		InsertRows(request.Cast<RESTInsertRowsRequest>());
		break;
	case RESTCommitRequestType::INSERT_FILES:
		InsertFiles(request.Cast<RESTInsertFilesRequest>());
		break;
	case RESTCommitRequestType::DELETE_DATA:
		DeleteData(request.Cast<RESTDeleteDataRequest>());
		break;
	default:
		throw InternalException("Unsupported RESTCommitRequestType");
	}
}

//===--------------------------------------------------------------------===//
// Unions
//===--------------------------------------------------------------------===//
JSONMutableValue RESTAlterationCodec::Write(JSONWriter &writer, const RESTAlteration &value) {
	auto result = writer.CreateObject();
	switch (value.type) {
	case RESTAlterationType::RENAME_TABLE:
		result.Add("rename_table", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTRenameTable>()));
		break;
	case RESTAlterationType::RENAME_VIEW:
		result.Add("rename_view", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTRenameView>()));
		break;
	case RESTAlterationType::RENAME_COLUMN:
		result.Add("rename_column", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTRenameColumn>()));
		break;
	case RESTAlterationType::RENAME_FIELD:
		result.Add("rename_field", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTRenameField>()));
		break;
	case RESTAlterationType::ADD_COLUMN:
		result.Add("add_column", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTAddColumn>()));
		break;
	case RESTAlterationType::ADD_FIELD:
		result.Add("add_field", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTAddField>()));
		break;
	case RESTAlterationType::REMOVE_COLUMN:
		result.Add("remove_column", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTRemoveColumn>()));
		break;
	case RESTAlterationType::REMOVE_FIELD:
		result.Add("remove_field", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTRemoveField>()));
		break;
	case RESTAlterationType::CHANGE_COLUMN_TYPE:
		result.Add("change_column_type", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTChangeColumnType>()));
		break;
	case RESTAlterationType::SET_DEFAULT:
		result.Add("set_default", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTSetDefault>()));
		break;
	case RESTAlterationType::SET_NOT_NULL:
		result.Add("set_not_null", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTSetNotNull>()));
		break;
	case RESTAlterationType::DROP_NOT_NULL:
		result.Add("drop_not_null", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTDropNotNull>()));
		break;
	case RESTAlterationType::SET_PARTITIONED_BY:
		result.Add("set_partitioned_by", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTSetPartitionedBy>()));
		break;
	case RESTAlterationType::SET_SORTED_BY:
		result.Add("set_sorted_by", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTSetSortedBy>()));
		break;
	case RESTAlterationType::SET_OPTIONS:
		result.Add("set_options", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTSetOptions>()));
		break;
	case RESTAlterationType::RESET_OPTIONS:
		result.Add("reset_options", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTResetOptions>()));
		break;
	case RESTAlterationType::SET_COMMENT:
		result.Add("set_comment", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTSetComment>()));
		break;
	case RESTAlterationType::SET_COLUMN_COMMENT:
		result.Add("set_column_comment", DuckLakeRESTSerializer::Write(writer, value.Cast<RESTSetColumnComment>()));
		break;
	default:
		throw InternalException("Unsupported RESTAlterationType");
	}
	return result;
}

void RESTAlterationCodec::Read(RESTJsonIn in, unique_ptr<RESTAlteration> &result) {
	auto members = in.Members();
	if (members.size() != 1) {
		throw InvalidInputException(
		    "DuckLake REST: a Alteration has to be an object with exactly one member, the name of the variant");
	}
	auto &name = members[0].first;
	if (name == "rename_table") {
		result = make_uniq<RESTRenameTable>(DuckLakeRESTSerializer::Read<RESTRenameTable>(members[0].second));
		return;
	}
	if (name == "rename_view") {
		result = make_uniq<RESTRenameView>(DuckLakeRESTSerializer::Read<RESTRenameView>(members[0].second));
		return;
	}
	if (name == "rename_column") {
		result = make_uniq<RESTRenameColumn>(DuckLakeRESTSerializer::Read<RESTRenameColumn>(members[0].second));
		return;
	}
	if (name == "rename_field") {
		result = make_uniq<RESTRenameField>(DuckLakeRESTSerializer::Read<RESTRenameField>(members[0].second));
		return;
	}
	if (name == "add_column") {
		result = make_uniq<RESTAddColumn>(DuckLakeRESTSerializer::Read<RESTAddColumn>(members[0].second));
		return;
	}
	if (name == "add_field") {
		result = make_uniq<RESTAddField>(DuckLakeRESTSerializer::Read<RESTAddField>(members[0].second));
		return;
	}
	if (name == "remove_column") {
		result = make_uniq<RESTRemoveColumn>(DuckLakeRESTSerializer::Read<RESTRemoveColumn>(members[0].second));
		return;
	}
	if (name == "remove_field") {
		result = make_uniq<RESTRemoveField>(DuckLakeRESTSerializer::Read<RESTRemoveField>(members[0].second));
		return;
	}
	if (name == "change_column_type") {
		result = make_uniq<RESTChangeColumnType>(DuckLakeRESTSerializer::Read<RESTChangeColumnType>(members[0].second));
		return;
	}
	if (name == "set_default") {
		result = make_uniq<RESTSetDefault>(DuckLakeRESTSerializer::Read<RESTSetDefault>(members[0].second));
		return;
	}
	if (name == "set_not_null") {
		result = make_uniq<RESTSetNotNull>(DuckLakeRESTSerializer::Read<RESTSetNotNull>(members[0].second));
		return;
	}
	if (name == "drop_not_null") {
		result = make_uniq<RESTDropNotNull>(DuckLakeRESTSerializer::Read<RESTDropNotNull>(members[0].second));
		return;
	}
	if (name == "set_partitioned_by") {
		result = make_uniq<RESTSetPartitionedBy>(DuckLakeRESTSerializer::Read<RESTSetPartitionedBy>(members[0].second));
		return;
	}
	if (name == "set_sorted_by") {
		result = make_uniq<RESTSetSortedBy>(DuckLakeRESTSerializer::Read<RESTSetSortedBy>(members[0].second));
		return;
	}
	if (name == "set_options") {
		result = make_uniq<RESTSetOptions>(DuckLakeRESTSerializer::Read<RESTSetOptions>(members[0].second));
		return;
	}
	if (name == "reset_options") {
		result = make_uniq<RESTResetOptions>(DuckLakeRESTSerializer::Read<RESTResetOptions>(members[0].second));
		return;
	}
	if (name == "set_comment") {
		result = make_uniq<RESTSetComment>(DuckLakeRESTSerializer::Read<RESTSetComment>(members[0].second));
		return;
	}
	if (name == "set_column_comment") {
		result = make_uniq<RESTSetColumnComment>(DuckLakeRESTSerializer::Read<RESTSetColumnComment>(members[0].second));
		return;
	}
	throw InvalidInputException("DuckLake REST: \"%s\" is not a valid Alteration", name);
}

