const unordered_map<string, rest_endpoint_t> &DuckLakeRESTAPI::GetEndpoints() {
	static const unordered_map<string, rest_endpoint_t> endpoints = {
	    {"config", ConfigEndpoint},
	    {"get_latest_snapshot", GetLatestSnapshotEndpoint},
	    {"get_metadata", GetMetadataEndpoint},
	    {"get_snapshot_at", GetSnapshotAtEndpoint},
	    {"list_snapshots", ListSnapshotsEndpoint},
	    {"select", SelectEndpoint},
	    {"table_changes", TableChangesEndpoint},
	    {"compact", CompactEndpoint},
	    {"commit_transaction", CommitTransactionEndpoint},
	};
	return endpoints;
}

const vector<RESTRoute> &DuckLakeRESTAPI::GetRoutes() {
	static const vector<RESTRoute> routes = {
	    {"config", "GET", "/v1/config", {{"catalog_name", RESTParameterType::STRING, "catalog"}}, true},
	    {"get_latest_snapshot",
	     "GET",
	     "/v1/snapshots/latest",
	     {{"include_catalog", RESTParameterType::BOOL, "include_catalog"},
	      {"include_stats", RESTParameterType::BOOL, "include_stats"},
	      {"cached_metadata_version", RESTParameterType::UINT, "cached_metadata_version"},
	      {"cached_data_version", RESTParameterType::UINT, "cached_data_version"}}},
	    {"get_metadata", "GET", "/v1/metadata", {}},
	    {"get_snapshot_at",
	     "GET",
	     "/v1/snapshots/at",
	     {{"include_catalog", RESTParameterType::BOOL, "include_catalog"},
	      {"include_stats", RESTParameterType::BOOL, "include_stats"},
	      {"cached_metadata_version", RESTParameterType::UINT, "cached_metadata_version"},
	      {"cached_data_version", RESTParameterType::UINT, "cached_data_version"},
	      {"unit", RESTParameterType::STRING, "unit"},
	      {"value", RESTParameterType::STRING, "value"},
	      {"bound", RESTParameterType::STRING, "bound"},
	      {"newest_snapshot_id", RESTParameterType::UINT, "newest_snapshot_id"}}},
	    {"list_snapshots",
	     "GET",
	     "/v1/snapshots",
	     {{"exclude_latest", RESTParameterType::BOOL, "exclude_latest"},
	      {"older_than", RESTParameterType::STRING, "older_than"},
	      {"snapshot_ids", RESTParameterType::UINT_LIST, "snapshot_id"},
	      {"page_size", RESTParameterType::UINT, "page_size"},
	      {"page_token", RESTParameterType::STRING, "page_token"}}},
	    {"select", "POST", "/v1/tables/{table_id}/scan", {{"table_id", RESTParameterType::UINT, ""}}},
	    {"table_changes", "POST", "/v1/tables/{table_id}/changes", {{"table_id", RESTParameterType::UINT, ""}}},
	    {"compact", "POST", "/v1/compactions", {}},
	    {"commit_transaction", "POST", "/v1/transactions/commit", {}},
	};
	return routes;
}

const RESTRoute &DuckLakeRESTAPI::GetRoute(const string &endpoint) {
	for (auto &route : GetRoutes()) {
		if (route.endpoint == endpoint) {
			return route;
		}
	}
	throw InternalException("DuckLake REST: unknown endpoint \"%s\"", endpoint);
}

void DuckLakeRESTAPI::ValidateResponse(const string &endpoint, const string &response_json) {
	RESTJsonReader document(response_json);
	if (endpoint == "config") {
		DuckLakeRESTSerializer::Read<RESTConfigResponse>(document.Root());
		return;
	}
	if (endpoint == "get_latest_snapshot") {
		DuckLakeRESTSerializer::Read<RESTSnapshotData>(document.Root());
		return;
	}
	if (endpoint == "get_metadata") {
		DuckLakeRESTSerializer::Read<DuckLakeMetadata>(document.Root());
		return;
	}
	if (endpoint == "get_snapshot_at") {
		DuckLakeRESTSerializer::Read<RESTSnapshotData>(document.Root());
		return;
	}
	if (endpoint == "list_snapshots") {
		DuckLakeRESTSerializer::Read<RESTListSnapshotsResponse>(document.Root());
		return;
	}
	if (endpoint == "select") {
		DuckLakeRESTSerializer::Read<RESTSelectResponse>(document.Root());
		return;
	}
	if (endpoint == "table_changes") {
		DuckLakeRESTSerializer::Read<RESTTableChangesResponse>(document.Root());
		return;
	}
	if (endpoint == "compact") {
		DuckLakeRESTSerializer::Read<RESTCompactResponse>(document.Root());
		return;
	}
	if (endpoint == "commit_transaction") {
		DuckLakeRESTSerializer::Read<RESTCommitTransactionResponse>(document.Root());
		return;
	}
}

